/// М-04 (TK-206, вердикт Судьи 09:20): `lot_first=k` меняет размер только у `touch_index == 0`; остальные касания —
/// байт в байт как без ключа (`first_k = None`); k = 1 — вся сутки как без ключа.
#[test]
fn lot_first_scales_only_first_touch_of_the_level() {
    let lot = PoolLot {
        min_order_qty_e9: 1_000_000,
        qty_step_e9: 1_000_000,
        min_notional_value_e9: 5_000_000_000,
    };
    let tick_e9 = 10_000_000; // 0.01
    let mut touches = Vec::new();
    for (i, idx) in [0_u32, 1, 2, 0, 3].into_iter().enumerate() {
        let mut t = probe_touch();
        t.price_tick = 1_000 + 100 * i as i64;
        t.touch_index = idx;
        touches.push(t);
    }
    let day = super::super::cache::DayTouches {
        day: "2026-01-01".to_string(),
        touches,
        approaches: None,
        rets: Vec::new(),
    };
    let sizing = OrderSizing::Usd(lot, 100.0);
    let grid = (tick_e9, 1_000_000);
    let base = super::super::steps::day_order_qtys(&sizing, &day, None, grid, 1, None).unwrap();
    let one = super::super::steps::day_order_qtys(&sizing, &day, None, grid, 1, Some(1.0)).unwrap();
    assert_eq!(base, one, "k = 1 — как без ключа");
    let k2 = super::super::steps::day_order_qtys(&sizing, &day, None, grid, 1, Some(2.0)).unwrap();
    let k3 = super::super::steps::day_order_qtys(&sizing, &day, None, grid, 1, Some(0.375)).unwrap();
    for (i, t) in day.touches.iter().enumerate() {
        if t.touch_index == 0 {
            assert!((k2[i] - 2.0 * base[i]).abs() < 1e-9, "{i}: {} vs {}", k2[i], base[i]);
            // кратно шагу 0.001 и не больше 0.375 номинала
            let steps = k3[i] / 0.001;
            assert!((steps - steps.round()).abs() < 1e-6, "{i}: {}", k3[i]);
            assert!(k3[i] <= 0.375 * base[i] + 1e-12 && k3[i] > 0.375 * base[i] - 0.001);
        } else {
            assert_eq!(k2[i].to_bits(), base[i].to_bits(), "{i}: touch_index≠0 не тронут");
            assert_eq!(k3[i].to_bits(), base[i].to_bits(), "{i}: touch_index≠0 не тронут");
        }
    }
    assert!(day.touches.iter().any(|t| t.touch_index == 0) && day.touches.iter().any(|t| t.touch_index != 0));
}

